def jsonToDataset_NoID(jsonStr, key1):

	def _safeJsonDecode(s):
		try:
			return system.util.jsonDecode(s)
		except:
			if isinstance(s, basestring) and len(s) >= 2 and s[0] == '"' and s[-1] == '"':
				try:
					unescaped = s[1:-1].replace(r'\"', '"')
					return system.util.jsonDecode(unescaped)
				except:
					return []
			return []

	parsed = _safeJsonDecode(jsonStr) or []

	# 2) Build fast lookup: {papoitemID: answer}
	jsonMap = {}
	for obj in parsed:
		try:
			pid = int(obj.get("papoitemID"))
			jsonMap[pid] = obj.get("answer", None)
		except:
			continue

	# 3) Determine the description column name in key1 ("Description" or "Descripcion")
	descCol = "Description" if "Description" in key1.getColumnNames() else "Descripcion"

	# 4) Build output rows in the same order as key1
	headers = ["Description", "Answer"]
	rows = []
	for r in range(key1.getRowCount()):
		desc = key1.getValueAt(r, descCol)
		idVal = key1.getValueAt(r, "ID")
		try:
			idInt = int(idVal)
		except:
			idInt = None
		answer = jsonMap.get(idInt, None)  # leave blank (None) if not found
		rows.append([desc, answer])

	return system.dataset.toDataSet(headers, rows)


