"""Accumulate one new column only when `refresh` is True; clear when `reset` is True.

Behavior:
- On reset=True: return only ['Description'] and clear history (nombres se "reinician" implícitamente).
- On refresh=True: fetch latest answers, build ONE new column, and prepend it.
- On refresh=False: return previous dataset (or empty if none).
- No edge detection: flags are read as-is.
- History is stored in self.custom.dsTable.

DataAnswer JSON formats supported:
- Legacy list: [ { "papoitemID": .., "answer": .., ... }, ... ]
- New object: { "items": [ { "papoItemID": .., "answer": .., "registerTypeID": .. }, ..., {"insights": "..."} ] }
"""

# ------------------------
# 0) Config & inputs
# ------------------------
default_papo_id = 1
default_node_id = 4
default_rtids = range(1, 9)
delimiter = u' | '
always_add = False

rtid_labels = {
	1: u'Una hora',
	2: u'Dos horas',
	3: u'Media hora',
	4: u'Cuatro horas',
	5: u'Cambio de referencia',
	6: u'Mantenimiento',
	7: u'Inicio de turno',
	8: u'Fin de turno',
	1002: u'Mitad de turno',
}

def _to_bool(x):
	try:
		if isinstance(x, basestring):
			return x.strip().lower() in ('1', 'true', 't', 'yes', 'y', 'on')
		return bool(x)
	except:
		return False

# Resolve DB, IDs, etc.
db = None
papo_id = default_papo_id
node_id = default_node_id
rtids = default_rtids

if isinstance(value, dict):
	db = value.get('db', None)
	papo_id = value.get('papoID', default_papo_id)
	node_id = value.get('nodeID', default_node_id)
	rtids = value.get('rtids', default_rtids)
	delimiter = value.get('delimiter', delimiter)
	always_add = _to_bool(value.get('alwaysAdd', always_add))

# DB fallback
if not db:
	try:
		db = getattr(self.custom, 'dbConnection', None)
	except:
		db = None

# Flags: prefer view.custom → value → self.custom
def _get_flag(name, default=False):
	try:
		return _to_bool(getattr(self.view.custom, name))
	except:
		pass
	if isinstance(value, dict) and name in value:
		return _to_bool(value.get(name, default))
	try:
		return _to_bool(getattr(self.custom, name, default))
	except:
		return default

refresh = _get_flag('refresh', False)
reset = _get_flag('reset', False)

# Column naming hint (tipo de registro)
selected_rtid_for_label = None
try:
	lrt = getattr(self.custom, 'lastRegisterType', None)
	if lrt is not None and unicode(lrt).strip() != u'':
		selected_rtid_for_label = int(lrt)
except:
	selected_rtid_for_label = None

# ------------------------
# 1) Load item catalog (always build baseline)
# ------------------------
query_items = u'''
	SELECT Description, ID
	FROM papo.dbo.papoitem
	WHERE PapoID = ?
	ORDER BY 
		CASE RegisterTypeID
			WHEN 7 THEN 1
			WHEN 3 THEN 2
			WHEN 1 THEN 3
			WHEN 2 THEN 4
			ELSE 5
		END;
'''
ds_items = system.db.runPrepQuery(query_items, [papo_id], db)
item_count = ds_items.getRowCount()
item_ids = []
item_descs = []
for r in range(item_count):
	item_descs.append(ds_items.getValueAt(r, 'Description'))
	item_ids.append(int(ds_items.getValueAt(r, 'ID')))

def _empty_ds():
	return system.dataset.toDataSet(['Description'], [[d] for d in item_descs])

# ------------------------
# 2) RESET → clear and return only Description
# ------------------------
if reset:
	out_ds = _empty_ds()
	try:
		self.custom.dsTable = out_ds
	except:
		pass
	return out_ds

# ------------------------
# 3) If refresh is FALSE → return previous (or empty)
# ------------------------
try:
	prev_ds = getattr(self.custom, 'dsTable', None)
except:
	prev_ds = None
if not refresh:
	return prev_ds if prev_ds is not None else _empty_ds()

# ------------------------
# 4) JSON helpers (ADAPTED)
# ------------------------
def _safe_json_decode(s):
	if isinstance(s, (list, dict)):
		return s
	if s is None:
		return []
	try:
		return system.util.jsonDecode(s)
	except:
		pass
	try:
		if isinstance(s, basestring):
			txt = s.strip()
			if len(txt) >= 2 and txt[0] == '"' and txt[-1] == '"':
				unescaped = txt[1:-1].replace(r'\"', '"')
				return system.util.jsonDecode(unescaped)
	except:
		pass
	return []

def _extract_items(json_value):
	parsed = _safe_json_decode(json_value) or []
	if isinstance(parsed, dict):
		items = parsed.get('items', [])
		if isinstance(items, basestring):
			items = _safe_json_decode(items) or []
		return items if isinstance(items, list) else []
	elif isinstance(parsed, list):
		return parsed
	else:
		return []

def _json_to_map(json_value, filter_rtid=None):
	items = _extract_items(json_value)
	out = {}
	for obj in items:
		if not isinstance(obj, dict):
			continue
		if filter_rtid is not None:
			rt_in = obj.get('registerTypeID', None)
			if rt_in not in (filter_rtid, unicode(filter_rtid), str(filter_rtid)):
				continue
		pid_raw = obj.get('papoItemID', obj.get('papoitemID', None))
		if pid_raw is None:
			continue  # e.g., {"insights": "..."}
		try:
			pid = int(pid_raw)
		except:
			continue
		out[pid] = obj.get('answer', None)
	return out

def _is_empty(v):
	if v is None:
		return True
	try:
		if isinstance(v, basestring):
			return len(v.strip()) == 0
		if isinstance(v, (list, tuple, dict)):
			return len(v) == 0
	except:
		return False

def _to_text(v):
	try:
		return unicode(v)
	except:
		try:
			return str(v)
		except:
			return u''

def _fetch_latest_dataanswer(rtid, papo_id, node_id, db):
	q = u'''
		SELECT TOP 1 DataAnswer
		FROM registerhistory
		WHERE RegisterTypeID = ? AND PapoID = ? AND NodeID = ?
		ORDER BY ID DESC;
	'''
	ds = system.db.runPrepQuery(q, [rtid, papo_id, node_id], db)
	return ds.getValueAt(0, 0) if ds.getRowCount() > 0 else '[]'

# ------------------------
# 5) REFRESH=True → build ONE new column
# ------------------------
# Previous columns
existing_cols = []
prev_idx_by_desc = {}
prev_ds_ref = None
if prev_ds is not None:
	try:
		col_names = list(prev_ds.getColumnNames())
		existing_cols = [c for c in col_names if c != 'Description']
		if 'Description' in col_names:
			for rr in range(prev_ds.getRowCount()):
				prev_idx_by_desc[prev_ds.getValueAt(rr, 'Description')] = rr
			prev_ds_ref = prev_ds
	except:
		existing_cols, prev_idx_by_desc, prev_ds_ref = [], {}, None

# Read latest answers for each RTID
rtid_maps = []
for rtid in list(rtids):
	js = _fetch_latest_dataanswer(rtid, papo_id, node_id, db)
	amap = _json_to_map(json_value=js, filter_rtid=rtid)
	if any(not _is_empty(amap.get(_id)) for _id in item_ids):
		rtid_maps.append((rtid, amap))

# Aggregate into one column
new_col_vals_by_id = {}
for _id in item_ids:
	parts = []
	for (rtid, amap) in rtid_maps:
		val = amap.get(_id, None)
		if not _is_empty(val):
			parts.append(_to_text(val))
	new_col_vals_by_id[_id] = (delimiter.join(parts) if parts else None)

# ------------------------
# 6) Column naming WITHOUT custom counters (derivado solo de columnas existentes)
# ------------------------

	if selected_rtid_for_label is not None:
		base_name = rtid_labels.get(selected_rtid_for_label, u'RTID {0}'.format(selected_rtid_for_label))
	else:
		base_name = u'Answer'

	def _next_seq_for_base(cols, base):
		"""Devuelve siguiente secuencia para 'base' mirando cols existentes.
		Reconoce:
		  - 'base'
		  - 'base N'
		Si hay una columna exacta 'base' (sin número), cuenta como 1.
		Si no hay nada, devuelve 1.
		"""
		max_n = 0
		found_plain = False
		for c in cols:
			try:
				name = unicode(c)
			except:
				name = u''
			if name == base:
				found_plain = True
				if max_n < 1:
					max_n = 1
				continue
			if name.startswith(base + u' '):
				suf = name[len(base) + 1:]  # después de "base "
				try:
					n = int(suf)
					if n > max_n:
						max_n = n
				except:
					continue
		if max_n == 0:
			return 1
		return max_n + 1

	seq_num = _next_seq_for_base(existing_cols, base_name)
	new_col_name = u'%s %d' % (base_name, seq_num)
# ------------------------
# 7) Compose final dataset
# ------------------------
out_cols = ['Description', new_col_name] + existing_cols
rows = []
for i in range(item_count):
	desc = item_descs[i]
	new_val = new_col_vals_by_id.get(item_ids[i], None)
	prev_vals = []
	if prev_ds_ref is not None:
		row_idx = prev_idx_by_desc.get(desc, None)
		for cname in existing_cols:
			if row_idx is None:
				prev_vals.append(None)
			else:
				try:
					prev_vals.append(prev_ds_ref.getValueAt(row_idx, cname))
				except:
					prev_vals.append(None)
	rows.append([desc, new_val] + prev_vals)

out_ds = system.dataset.toDataSet(out_cols, rows)

# Persist and return
try:
	self.custom.dsTable = out_ds
except:
	pass
return out_ds

